package com.company.tpm.attendance;import com.company.tpm.audit.AuditService;import com.company.tpm.employee.*;import com.company.tpm.schedule.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AttendanceService{private final AttendanceRepository records;private final TrainingSessionRepository sessions;private final EmployeeRepository employees;private final AuditService audit;public AttendanceService(AttendanceRepository a,TrainingSessionRepository s,EmployeeRepository e,AuditService log){records=a;sessions=s;employees=e;audit=log;}
 @Transactional public Attendance record(UUID sessionId,UUID employeeId,Attendance.Status status,String actor,String remark){var session=sessions.findById(sessionId).orElseThrow(()->new IllegalArgumentException("Session not found"));var employee=employees.findById(employeeId).orElseThrow(()->new IllegalArgumentException("Employee not found"));var existing=records.findBySessionIdAndEmployeeId(sessionId,employeeId);Attendance result;if(existing.isPresent()){result=existing.get();var previous=result.getStatus();result.correct(status,actor,remark);audit.record(actor,"ATTENDANCE_UPDATED","Attendance",result.getId(),Map.of("previous",previous.name(),"next",status.name()));}else{result=records.save(new Attendance(session,employee,status,actor));audit.record(actor,"ATTENDANCE_CREATED","Attendance",result.getId(),Map.of("status",status.name()));}return result;}}
